    aWandererD = 0x9611C47C5543CBE1ULL;
    aWandererE = 0xAC03C159511F3B1BULL;
    aWandererF = 0xB3B15D6F5CDC1F3BULL;
    aWandererG = 0xFDAACB3D8CABA239ULL;
    aWandererH = 0xD2E0CBF3DEFADE12ULL;
    aWandererI = 0xDB3C1BB6B9D0DE7FULL;
    aWandererJ = 0xA8214340FC9368F3ULL;
    aWandererK = 0xA2CFAFB2BB4F2973ULL;

    ////////////////////////////////////////////////////////
    //
    // Main twist loops
    //
    TwistExpander_Canopus_Arx::TWIST_A(PARAMS_TWIST);

    TwistExpander_Canopus_Arx::TWIST_B(PARAMS_TWIST);

    TwistExpander_Canopus_Arx::TWIST_C(PARAMS_TWIST);

    std::uint64_t aDomainWordMatrixSelectA = pWorkSpace->mDomainBundle.mTwistConstants.mMatrixSelectA;
    std::uint64_t aDomainWordMatrixSelectB = pWorkSpace->mDomainBundle.mTwistConstants.mMatrixSelectB;

    std::uint8_t aDomainWordMatrixUnrollA = pWorkSpace->mDomainBundle.mTwistConstants.mMatrixUnrollA;
    std::uint8_t aDomainWordMatrixUnrollB = pWorkSpace->mDomainBundle.mTwistConstants.mMatrixUnrollB;

